// Initialize investment committee process
const data = $input.item.json;

// Create a structured investment committee object
const icRequest = {
  id: `IC-${Date.now()}`,
  companyName: data.companyName,
  dueDiligenceId: data.dueDiligenceId || '',
  requestDate: new Date().toISOString(),
  meetingDate: data.meetingDate || '',
  status: 'Pending',
  dealSponsor: data.dealSponsor || '',
  requestedAmount: data.requestedAmount || '',
  valuation: data.valuation || '',
  stage: data.stage || '',
  industry: data.industry || '',
  committeeMembers: data.committeeMembers || [
    'partner1@vcfirm.com',
    'partner2@vcfirm.com',
    'partner3@vcfirm.com',
    'partner4@vcfirm.com'
  ],
  votes: {},
  quorum: Math.ceil((data.committeeMembers || []).length / 2),
  decision: '',
  decisionDate: '',
  decisionNotes: '',
  materials: []
};

// Create folder structure for documents
const folderStructure = {
  mainFolder: `${icRequest.companyName} - Investment Committee`,
  subFolders: [
    'Due Diligence Reports',
    'Financial Analysis',
    'Market Research',
    'Presentation Materials',
    'Meeting Notes',
    'Decision Documents'
  ]
};

return {
  json: {
    icRequest,
    folderStructure
  }
};

// Prepare data for creating sub folders
const mainFolderId = $input.first().json.id;
const folderStructure = $input.first().json.folderStructure;

// Create an array of items for the sub folders
const subFolders = folderStructure.subFolders.map(subFolder => {
  return {
    json: {
      subFolder,
      mainFolderId
    }
  };
});

return subFolders;

