// Check for upcoming IC meetings
const pendingMeetings = $input.item.json;

// If no pending meetings, return empty
if (!pendingMeetings) {
  return { json: { hasMeetingsToday: false } };
}

// Check if meeting is today
const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const tomorrow = new Date(today);
tomorrow.setDate(tomorrow.getDate() + 1);

const meetingDate = new Date(pendingMeetings.meetingDate);
const meetingDay = new Date(meetingDate.getFullYear(), meetingDate.getMonth(), meetingDate.getDate());

const isMeetingToday = meetingDay >= today && meetingDay < tomorrow;

return {
  json: {
    ...pendingMeetings,
    hasMeetingsToday: isMeetingToday,
    formattedMeetingDate: meetingDate.toLocaleString()
  }
};

