// Check for meetings that have ended and need voting forms
const pendingDecisions = $input.item.json;

// If no pending decisions, return empty
if (!pendingDecisions) {
  return { json: { needsVotingForm: false } };
}

// Check if meeting has ended
const now = new Date();
const meetingDate = new Date(pendingDecisions.meetingDate);
// Add 2 hours to meeting time to account for meeting duration
const meetingEndTime = new Date(meetingDate.getTime() + 2 * 60 * 60 * 1000);

const hasMeetingEnded = now > meetingEndTime;

return {
  json: {
    ...pendingDecisions,
    needsVotingForm: hasMeetingEnded,
    formattedMeetingDate: meetingDate.toLocaleString()
  }
};

// Create individual voting forms for each committee member
const committeeMembers = $input.item.json.committeeMembers.split(',');

// Create an array of items for each committee member
const memberItems = committeeMembers.map(memberEmail => {
  return {
    json: {
      ...$input.item.json,
      memberEmail
    }
  };
});

return memberItems;

