// Record vote and check if decision can be made
const icRequest = $input.first().json;
const voteData = $input.last().json;

// Parse existing votes if any
let votes = {};
if (icRequest.votes && typeof icRequest.votes === 'string') {
  try {
    votes = JSON.parse(icRequest.votes);
  } catch (e) {
    // If parsing fails, start with empty object
    votes = {};
  }
}

// Add new vote
votes[voteData.memberEmail] = {
  vote: voteData.vote,
  comments: voteData.comments,
  timestamp: new Date().toISOString()
};

// Count votes
const voteCount = {
  Approve: 0,
  Reject: 0,
  Abstain: 0,
  'Need More Information': 0
};

Object.values(votes).forEach(vote => {
  if (voteCount[vote.vote] !== undefined) {
    voteCount[vote.vote]++;
  }
});

// Check if we have enough votes to make a decision
const committeeMembers = icRequest.committeeMembers.split(',');
const totalVotes = Object.keys(votes).length;
const quorum = icRequest.quorum || Math.ceil(committeeMembers.length / 2);

// Determine if we have reached a decision
let decision = '';
let decisionDate = '';
let status = 'Pending';

if (totalVotes >= quorum) {
  // If majority approves, decision is Approved
  if (voteCount.Approve > committeeMembers.length / 2) {
    decision = 'Approved';
    decisionDate = new Date().toISOString();
    status = 'Approved';
  }
  // If majority rejects, decision is Rejected
  else if (voteCount.Reject > committeeMembers.length / 2) {
    decision = 'Rejected';
    decisionDate = new Date().toISOString();
    status = 'Rejected';
  }
  // If majority needs more info, decision is Deferred
  else if (voteCount['Need More Information'] > committeeMembers.length / 2) {
    decision = 'Deferred';
    decisionDate = new Date().toISOString();
    status = 'Deferred';
  }
  // If we have quorum but no majority, check if all votes are in
  else if (totalVotes === committeeMembers.length) {
    // If all votes are in and no majority, go with plurality
    if (voteCount.Approve > voteCount.Reject && voteCount.Approve > voteCount['Need More Information']) {
      decision = 'Approved';
      decisionDate = new Date().toISOString();
      status = 'Approved';
    } else if (voteCount.Reject > voteCount.Approve && voteCount.Reject > voteCount['Need More Information']) {
      decision = 'Rejected';
      decisionDate = new Date().toISOString();
      status = 'Rejected';
    } else {
      decision = 'Deferred';
      decisionDate = new Date().toISOString();
      status = 'Deferred';
    }
  }
}

// Update IC request with votes and decision
const updatedIcRequest = {
  ...icRequest,
  votes: JSON.stringify(votes),
  voteCount: JSON.stringify(voteCount),
  totalVotes,
  decision,
  decisionDate,
  status,
  lastUpdated: new Date().toISOString()
};

return { json: updatedIcRequest };

